eteStartupAttempt(b);if not F then M((E or"The FFlag startup checkpoint could not be saved.").." Auto apply will be quarantined on the next execution.",8);end;end);end;end;end;end)();(function()local function M(O,F)local b=0;for E=1,#O,1 do local m=O[E];if F(m)then b+=1;O[b]=m;end;end;for F=#O,b+1,-1 do O[F]=nil;end;end;local function O(F)return coroutine.status(F)~="dead";end;local function F(b)return b.Connected;end;_G.__CokeboysSpawnRuntimeTask(function()while getgenv().CokeboysScriptLoaded do task.wait(30);M(getgenv().__CokeboysRuntimeTasks,O);M(getgenv().__CokeboysRuntimeConnections,F);end;end);end)();_G.__CokeboysTrackRuntimeConnection(t:GetPropertyChangedSignal("CurrentCamera"):Connect(function()g=t.CurrentCamera or g;end));getgenv().__CokeboysPVPEventCollectorSource="-- Cokeboys shared event collector for PVP/PVE observers.\10-- Reports verified Blox Fruits server sightings to the Cokeboys Event API.\10-- Discord webhook delivery stays inside Cloudflare; this file contains no webhook URL or signing secret.\10-- The access key and temporary event credential remain in memory and are never written by this collector.\10\10local Players = game:GetService(\"Players\")\10local HttpService = game:GetService(\"HttpService\")\10local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\10local Lighting = game:GetService(\"Lighting\")\10local CollectionService = game:GetService(\"CollectionService\")\10local StarterGui = game:GetService(\"StarterGui\")\10\10local LocalPlayer = Players.LocalPlayer\10while not LocalPlayer do\10    task.wait()\10    LocalPlayer = Players.LocalPlayer\10end\10\10local Environment = type(getgenv) == \"function\" and getgenv() or _G\10local Supplied = type(Environment.CokeboysEventCollectorConfig) == \"table\"\10    and Environment.CokeboysEventCollectorConfig or {}\10\10-- If PVE is already observing this client, reuse it instead of sending the\10-- same sighting twice. PVP normally reaches this file without a PVE runtime.\10local existingPVE = Environment.CokeboysPVEEventReporter\10if Supplied.ReuseExisting ~= false and type(existingPVE) == \"table\"\10    and type(existingPVE.GetSnapshot) == \"function\" then\10    local ok, snapshot = pcall(existingPVE.GetSnapshot)\10    if ok and type(snapshot) == \"table\" and snapshot.Alive then\10        Environment.CokeboysEventCollector = existingPVE\10        return existingPVE\10    end\10end\10\10if type(Environment.CokeboysEventCollector) == \"table\"\10    and type(Environment.CokeboysEventCollector.Stop) == \"function\" then\10    pcall(Environment.CokeboysEventCollector.Stop, \"Reloaded\")\10end\10\10local function boundedNumber(value, fallback, minimum, maximum)\10    value = tonumber(value)\10    if not value then return fallback end\10    return math.clamp(value, minimum, maximum)\10end\10\10local function readSavedAccessKey()\10    if type(readfile) ~= \"function\" then return \"\" end\10    local ok, value = pcall(readfile, tostring(Supplied.KeyFile or \"cokeboys_key.txt\"))\10    if not ok or type(value) ~= \"string\" then return \"\" end\10    return value:match(\"^%s*(.-)%s*$\") or \"\"\10end\10\10local Config = {\10    CredentialURL = \"https://cokeboys-token.cokeboysclient.workers.dev/event-credential\",\10    APIBaseURL = \"https://cokeboys-event-api.cokeboysclient.workers.dev\",\10    AccessKey = tostring(Supplied.AccessKey or Supplied.Key or readSavedAccessKey()),\10    HWID = tostring(Supplied.HWID or Supplied.Hwid or \"\"),\10    AutoStart = Supplied.AutoStart ~= false,\10    Notifications = Supplied.Notifications == true,\10    Debug = Supplied.Debug == true,\10    -- Relevant instance/property signals request immediate scans. This slower\10    -- pass is only a safety net for executor or streaming events that were\10    -- missed, rather than rebuilding the entire event snapshot every 2s.\10    ScanInterval = boundedNumber(Supplied.ScanInterval, 10, 2, 30),\10    RequestSpacing = boundedNumber(Supplied.RequestSpacing, 10.5, 10.1, 30),\10    CredentialRefreshLead = boundedNumber(Supplied.CredentialRefreshLead, 300, 60, 900),\10    DealerStockInterval = boundedNumber(Supplied.DealerStockInterval, 20, 10, 60),\10    ReportOldServers = Supplied.ReportOldServers ~= false,\10}\10\10local PLACE_TO_SEA = {\10    [2753915549] = 1,\10    [85211729168715] = 1,\10    [4442272183] = 2,\10    [79091703265657] = 2,\10    [7449423635] = 3,\10    [100117331123089] = 3,\10}\10\10local MOON_TEXTURE_PHASES = {\10    [\"9709135895\"] = 1,\10    [\"9709139597\"] = 2,\10    [\"9709143733\"] = 3,\10    [\"9709149052\"] = 4,\10    [\"9709149431\"] = 5,\10    [\"9709149680\"] = 6,\10    [\"9709150086\"] = 7,\10    [\"9709150401\"] = 8,\10}\10\10local EVENT_REFRESH_SECONDS = {\10    fruit = 60,\10    berry = 85,\10    boss = 60,\10    legendary_haki = 85,\10    legendary_sword = 85,\10    near_full_moon = 240,\10    full_moon = 240,\10    mirage_island = 115,\10    kitsune_island = 115,\10    frozen_dimension = 60,\10    prehistoric_island = 115,\10    factory_raid = 60,\10    castle_raid = 60,\10    old_server = 85,\10}\10\10local EVENT_PRIORITY = {\10    fruit = 1,\10    frozen_dimension = 2,\10    mirage_island = 3,\10    kitsune_island = 3,\10    prehistoric_island = 3,\10    full_moon = 4,\10    near_full_moon = 5,\10    boss = 6,\10    legendary_haki = 7,\10    legendary_sword = 7,\10    factory_raid = 8,\10    castle_raid = 8,\10    berry = 9,\10    old_server = 10,\10}\10\10local BERRY_TYPES = {\10    [\"Blue Icicle Berry\"] = true,\10    [\"Green Toad Berry\"] = true,\10    [\"Orange Berry\"] = true,\10    [\"Pink Pig Berry\"] = true,\10    [\"Purple Jelly Berry\"] = true,\10    [\"Red Cherry Berry\"] = true,\10    [\"White Cloud Berry\"] = true,\10    [\"Yellow Star Berry\"] = true,\10}\10\10local ISLAND_EVENTS = {\10    { Type = \"mirage_island\", Names = { \"MysticIsland\", \"Mirage Island\" } },\10    { Type = \"kitsune_island\", Names = { \"KitsuneIsland\", \"Kitsune Island\" } },\10    { Type = \"frozen_dimension\", Names = { \"FrozenDimension\", \"Frozen Dimension\" } },\10    { Type = \"prehistoric_island\", Names = { \"PrehistoricIsland\", \"Prehistoric Island\" } },\10}\10\10local State = {\10    Alive = true,\10    Running = false,\10    DisabledByServer = false,\10    Status = \"Ready\",\10    LastError = nil,\10    Credential = nil,\10    ReporterId = nil,\10    CredentialExpiresAt = 0,\10    LastHTTPStatus = nil,\10    LastAccepted = nil,\10    LastRequestAt = -math.huge,\10    BackoffUntil = 0,\10    AuthBusy = false,\10    ScanRequested = true,\10    LastLegendarySwordCheck = -math.huge,\10    LegendarySwordStock = nil,\10    LegendarySwordVerifiedAt = -math.huge,\10    Detected = {},\10    Reported = {},\10    Pending = {},\10    Connections = {},\10}\10\10local Reporter = {\10    Version = \"1.1.0-shared-collector\",\10}\10\10local function notify(title, message)\10    if not Config.Notifications then return end\10    pcall(function()\10        StarterGui:SetCore(\"SendNotification\", {\10            Title = tostring(title),\10            Text = tostring(message),\10            Duration = 6,\10        })\10    end)\10end\10\10local function debugLog(message)\10    if Config.Debug then\10        warn(\"[Cokeboys Event Test] \" .. tostring(message))\10    end\10end\10\10local function setStatus(message, isError)\10    State.Status = tostring(message or \"\")\10    if isError then State.LastError = State.Status end\10    debugLog(State.Status)\10end\10\10local function resolveRequestFunction()\10    local candidates = {\10        rawget(Environment, \"request\"),\10        rawget(Environment, \"http_request\"),\10        rawget(_G, \"request\"),\10        rawget(_G, \"http_request\"),\10    }\10    local synTable = rawget(Environment, \"syn\") or rawget(_G, \"syn\")\10    if type(synTable) == \"table\" then table.insert(candidates, 1, synTable.request) end\10    local httpTable = rawget(Environment, \"http\") or rawget(_G, \"http\")\10    if type(httpTable) == \"table\" then table.insert(candidates, httpTable.request) end\10    for _, candidate in pairs(candidates) do\10        if type(candidate) == \"function\" then return candidate end\10    end\10    return nil\10end\10\10local RequestFunction = resolveRequestFunction()\10\10local function normalizeResponse(response)\10    if type(response) ~= \"table\" then\10        return { StatusCode = 0, Body = \"\", Headers = {}, Error = \"Executor returned no HTTP response\" }\10    end\10    return {\10        StatusCode = tonumber(response.StatusCode or response.Status or response.status_code) or 0,\10        Body = tostring(response.Body or response.body or response.ResponseBody or \"\"),\10        Headers = type(response.Headers or response.headers) == \"table\" and (response.Headers or response.headers) or {},\10    }\10end\10\10local function httpRequest(method, url, body, headers)\10    if not RequestFunction then\10        return nil, \"This executor does not expose a supported HTTP request function\"\10    end\10    local requestHeaders = headers or {}\10    requestHeaders[\"Accept\"] = \"application/json\"\10    if body ~= nil then requestHeaders[\"Content-Type\"] = \"application/json\" end\10    local ok, response = pcall(RequestFunction, {\10        Url = url,\10        URL = url,\10        Method = method,\10        Headers = requestHeaders,\10        Body = body,\10    })\10    if not ok then return nil, tostring(response) end\10    local normalized = normalizeResponse(response)\10    State.LastHTTPStatus = normalized.StatusCode\10    return normalized\10end\10\10local function decodeJSON(text)\10    if type(text) ~= \"string\" or text == \"\" then return nil end\10    local ok, result = pcall(HttpService.JSONDecode, HttpService, text)\10    return ok and type(result) == \"table\" and result or nil\10end\10\10local function unixNow()\10    local serverOk, serverValue = pcall(workspace.GetServerTimeNow, workspace)\10    if serverOk and tonumber(serverValue) then return math.floor(tonumber(serverValue)) end\10    local ok, value = pcall(function() return DateTime.now().UnixTimestamp end)\10    return ok and tonumber(value) or os.time()\10end\10\10local function resolveHWID()\10    if Config.HWID ~= \"\" then return Config.HWID end\10    for _, name in ipairs({ \"gethwid\", \"get_hwid\", \"gethardwareid\", \"get_hardware_id\" }) do\10        local candidate = rawget(Environment, name) or rawget(_G, name)\10        if type(candidate) == \"function\" then\10            local ok, value = pcall(candidate)\10            if ok and type(value) == \"string\" and value ~= \"\" then\10                Config.HWID = value\10                return value\10            end\10        end\10    end\10    local ok, value = pcall(function()\10        return game:GetService(\"RbxAnalyticsService\"):GetClientId()\10    end)\10    if ok and value ~= nil and tostring(value) ~= \"\" then\10        Config.HWID = tostring(value)\10    else\10        Config.HWID = tostring(LocalPlayer.UserId)\10    end\10    return Config.HWID\10end\10\10local function serverUptime()\10    local sharedClock = Environment.__CokeboysServerClock\10    if type(sharedClock) == \"table\"\10        and tostring(sharedClock.jobId) == tostring(game.JobId)\10        and tonumber(sharedClock.startedAt) then\10        return math.max(0, math.floor(unixNow() - tonumber(sharedClock.startedAt)))\10    end\10    local ok, value = pcall(function() return workspace.DistributedGameTime end)\10    if ok and tonumber(value) then return math.max(0, math.floor(tonumber(value))) end\10    return nil\10end\10\10local function serverRegion()\10    local info = Environment.CokeboysServerInfo\10    local region = type(info) == \"table\" and tostring(info.region or \"\") or \"\"\10    if region == \"\" or region == \"Unavailable\" or region == \"ERROR\" then return nil end\10    return region:sub(1, 80)\10end\10\10local function cleanValue(value)\10    value = tostring(value or \"\"):gsub(\"[%c]\", \"\"):match(\"^%s*(.-)%s*$\") or \"\"\10    return value:sub(1, 64)\10end\10\10local function eventKey(eventType, value)\10    return tostring(eventType) .. \"\\0\" .. tostring(value or \"\")\10end\10\10local function addEvent(events, eventType, value)\10    value = cleanValue(value)\10    if EVENT_REFRESH_SECONDS[eventType] and (#value > 0 or not (\10        eventType == \"fruit\" or eventType == \"berry\" or eventType == \"boss\"\10        or eventType == \"legendary_haki\" or eventType == \"legendary_sword\"\10    )) then\10        local key = eventKey(eventType, value)\10        events[key] = { Type = eventType, Value = value, Key = key }\10    end\10end\10\10local function isFruitTool(object)\10    if not object or not object:IsA(\"Tool\") or not object:FindFirstChild(\"Handle\") then return false end\10    local name = object.Name:lower()\10    local tooltip = tostring(object.ToolTip or \"\"):lower()\10    return name:find(\"fruit\", 1, true) ~= nil or tooltip:find(\"fruit\", 1, true) ~= nil\10end\10\10local function fruitDisplayName(object)\10    local value = tostring(object:GetAttribute(\"OriginalName\") or object.Name or \"Unknown Fruit\")\10    if value:sub(-6) == \" Fruit\" then return value end\10    local repeated = value:match(\"^([^%-]+)%-\")\10    if repeated and repeated ~= \"\" then value = repeated end\10    return value .. \" Fruit\"\10end\10\10local function scanFruits(events)\10    local function scanContainer(container)\10        if not container then return end\10        for _, object in ipairs(container:GetChildren()) do\10            if isFruitTool(object) then addEvent(events, \"fruit\", fruitDisplayName(object)) end\10        end\10    end\10    scanContainer(workspace)\10    scanContainer(workspace:FindFirstChild(\"_WorldOrigin\"))\10end\10\10local function scanBerries(events)\10    local ok, bushes = pcall(CollectionService.GetTagged, CollectionService, \"BerryBush\")\10    if not ok or type(bushes) ~= \"table\" then return end\10    for _, tagged in ipairs(bushes) do\10        if tagged and tagged:IsDescendantOf(workspace) then\10            for _, descendant in ipairs(tagged:GetDescendants()) do\10                if descendant:IsA(\"ProximityPrompt\") then\10                    for _, candidate in ipairs({\10                        descendant.ActionText,\10                        descendant.ObjectText,\10                        descendant.Parent and descendant.Parent.Name or \"\",\10                    }) do\10                        if BERRY_TYPES[candidate] then addEvent(events, \"berry\", candidate) end\10                    end\10                end\10            end\10        end\10    end\10end\10\10local function stripBossName(name)\10    name = tostring(name or \"\")\10    name = name:gsub(\"%s*%[Lv%.?[^%]]*%]\", \"\")\10    name = name:gsub(\"%s*%[Raid Boss%]\", \"\")\10    name = name:gsub(\"%s*%[Boss%]\", \"\")\10    return cleanValue(name)\10end\10\10local function scanBosses(events)\10    local enemies = workspace:FindFirstChild(\"Enemies\")\10    if not enemies then return end\10    for _, enemy in ipairs(enemies:GetChildren()) do\10        local humanoid = enemy:FindFirstChildOfClass(\"Humanoid\")\10        if humanoid and humanoid.Health > 0 then\10            local identity = (enemy.Name .. \" \" .. tostring(humanoid.DisplayName or \"\")):lower()\10            local boss = identity:find(\"raid boss\", 1, true) ~= nil\10                or identity:find(\"[boss]\", 1, true) ~= nil\10                or enemy:GetAttribute(\"Boss\") == true\10                or enemy:GetAttribute(\"IsBoss\") == true\10                or enemy:GetAttribute(\"RaidBoss\") == true\10                or humanoid:GetAttribute(\"Boss\") == true\10                or humanoid:GetAttribute(\"IsBoss\") == true\10                or humanoid:GetAttribute(\"RaidBoss\") == true\10            if boss then addEvent(events, \"boss\", stripBossName(enemy.Name)) end\10        end\10    end\10end\10\10local function hasNamedWorldObject(names)\10    local roots = {\10        workspace:FindFirstChild(\"Map\"),\10        workspace:FindFirstChild(\"_WorldOrigin\") and workspace._WorldOrigin:FindFirstChild(\"Locations\"),\10    }\10    for _, root in ipairs(roots) do\10        if root then\10            for _, name in ipairs(names) do\10                local instance = root:FindFirstChild(name, true)\10                if instance then\10                    if instance:IsA(\"BasePart\") then return true end\10                    if instance:IsA(\"Model\") and instance:FindFirstChildWhichIsA(\"BasePart\", true) then return true end\10                end\10            end\10        end\10    end\10    return false\10end\10\10local function scanMoon(events)\10    local sky = Lighting:FindFirstChildOfClass(\"Sky\")\10    local texture = sky and tostring(sky.MoonTextureId) or \"\"\10    local phase = MOON_TEXTURE_PHASES[texture:match(\"(%d+)\") or \"\"]\10    local attributePhase = math.floor(tonumber(Lighting:GetAttribute(\"MoonPhase\")) or 0)\10    if not phase and attributePhase >= 1 and attributePhase <= 8 then phase = attributePhase end\10    if phase == 5 then\10        addEvent(events, \"full_moon\")\10    elseif phase == 4 then\10        addEvent(events, \"near_full_moon\")\10    end\10end\10\10local function scanIslands(events)\10    for _, definition in ipairs(ISLAND_EVENTS) do\10        if hasNamedWorldObject(definition.Names) then addEvent(events, definition.Type) end\10    end\10end\10\10local function normalizedName(value)\10    return tostring(value or \"\"):lower():gsub(\"[^%w]\", \"\")\10end\10\10local LEGENDARY_SWORD_NAMES = {\10    saddi = true,\10    shisui = true,\10    wando = true,\10    saishi = true,\10    shizu = true,\10    oroshi = true,\10}\10\10local NPCManager\10local NPCManagerResolved = false\10\10local function getNPCManager()\10    if NPCManagerResolved then return NPCManager end\10    NPCManagerResolved = true\10    local managerModule = ReplicatedStorage:FindFirstChild(\"NPCManager\")\10    if not managerModule or not managerModule:IsA(\"ModuleScript\") then return nil end\10    local ok, manager = pcall(require, managerModule)\10    if ok and type(manager) == \"table\" and type(manager.getNPCsByName) == \"function\" then\10        NPCManager = manager\10    end\10    return NPCManager\10end\10\10local function legendarySwordDealerPresent()\10    local npcs = workspace:FindFirstChild(\"NPCs\")\10    if npcs then\10        for _, npc in ipairs(npcs:GetChildren()) do\10            if normalizedName(npc.Name) == \"legendarysworddealer\" then return true end\10        end\10    end\10\10    -- NPCManager keeps distant optimized NPCs outside workspace while still\10    -- exposing their real model. This prevents streaming distance from hiding\10    -- an active dealer from the collector.\10    local manager = getNPCManager()\10    if not manager then return false end\10    local ok, listed = pcall(manager.getNPCsByName, \"Legendary Sword Dealer\")\10    if not ok or type(listed) ~= \"table\" then return false end\10    for _, candidate in ipairs(listed) do\10        if type(candidate) == \"table\" and type(candidate.getModel) == \"function\" then\10            local modelOk, model = pcall(candidate.getModel, candidate)\10            if modelOk and typeof(model) == \"Instance\" then return true end\10        end\10    end\10    return false\10end\10\10local function readLegendarySwordStock()\10    local nowClock = os.clock()\10    if nowClock - State.LastLegendarySwordCheck < Config.DealerStockInterval then\10        return State.LegendarySwordStock\10    end\10    State.LastLegendarySwordCheck = nowClock\10\10    local remotes = ReplicatedStorage:FindFirstChild(\"Remotes\")\10    local command = remotes and remotes:FindFirstChild(\"CommF_\")\10    if not command or not command:IsA(\"RemoteFunction\") then\10        if nowClock - State.LegendarySwordVerifiedAt > Config.DealerStockInterval * 2 then\10            State.LegendarySwordStock = nil\10        end\10        return State.LegendarySwordStock\10    end\10\10    -- Option 1 is the game's read-only stock query. Option 2 purchases the\10    -- sword and is deliberately never called by this reporting-only collector.\10    local ok, result = pcall(command.InvokeServer, command, \"LegendarySwordDealer\", \"1\")\10    if ok then\10        local stock = type(result) == \"string\" and cleanValue(result) or \"\"\10        if stock ~= \"\" and LEGENDARY_SWORD_NAMES[normalizedName(stock)] then\10            State.LegendarySwordStock = stock\10            State.LegendarySwordVerifiedAt = nowClock\10        else\10            State.LegendarySwordStock = nil\10            State.LegendarySwordVerifiedAt = -math.huge\10        end\10    elseif nowClock - State.LegendarySwordVerifiedAt > Config.DealerStockInterval * 2 then\10        State.LegendarySwordStock = nil\10    end\10    return State.LegendarySwordStock\10end\10\10local function scanDealers(events)\10    local npcs = workspace:FindFirstChild(\"NPCs\")\10    if npcs then\10        for _, npc in ipairs(npcs:GetChildren()) do\10            local name = normalizedName(npc.Name)\10            if name == \"masterofauras\" or name == \"colorhaki\" or name == \"colorsdealer\" then\10                addEvent(events, \"legendary_haki\", \"Master of Auras\")\10            end\10        end\10    end\10\10    if PLACE_TO_SEA[game.PlaceId] == 2 and legendarySwordDealerPresent() then\10        local stock = readLegendarySwordStock()\10        if stock then addEvent(events, \"legendary_sword\", stock) end\10    else\10        State.LegendarySwordStock = nil\10        State.LegendarySwordVerifiedAt = -math.huge\10    end\10end\10\10local function scanRaids(events)\10    local enemies = workspace:FindFirstChild(\"Enemies\")\10    local factoryCore = enemies and enemies:FindFirstChild(\"Core\")\10    local coreHumanoid = factoryCore and factoryCore:FindFirstChildOfClass(\"Humanoid\")\10    if coreHumanoid and coreHumanoid.Health > 0 then addEvent(events, \"factory_raid\") end\10\10    -- References consistently identify live Pirate Raid enemies by their\10    -- proximity to the Castle on the Sea rather than by NPC name.\10    if PLACE_TO_SEA[game.PlaceId] == 3 and enemies then\10        local castleCenter = Vector3.new(-5515.083, 343.113, -3013.252)\10        for _, enemy in ipairs(enemies:GetChildren()) do\10            local root = enemy:FindFirstChild(\"HumanoidRootPart\")\10            local humanoid = enemy:FindFirstChildOfClass(\"Humanoid\")\10            if root and humanoid and humanoid.Health > 0\10                and (root.Position - castleCenter).Magnitude <= 2000 then\10                addEvent(events, \"castle_raid\")\10                break\10            end\10        end\10    end\10\10    -- Kept as a controlled fallback until live testing confirms every raid\10    -- variant uses the same Castle radius marker.\10    if Environment.CokeboysCastleRaidActive == true then addEvent(events, \"castle_raid\") end\10end\10\10local function scanEvents()\10    local events = {}\10    scanFruits(events)\10    scanBerries(events)\10    scanBosses(events)\10    scanMoon(events)\10    scanIslands(events)\10    scanDealers(events)\10    scanRaids(events)\10    local uptime = serverUptime()\10    if Config.ReportOldServers and uptime and uptime >= 14400 then addEvent(events, \"old_server\") end\10    return events\10end\10\10local function requestScan()\10    if State.Alive then State.ScanRequested = true end\10end\10\10local function trackSignal(signal, callback)\10    local ok, connection = pcall(function() return signal:Connect(callback) end)\10    if ok and connection then State.Connections[#State.Connections + 1] = connection end\10    return connection\10end\10\10local EVENT_WORLD_NAMES = {}\10for _, definition in ipairs(ISLAND_EVENTS) do\10    for _, name in ipairs(definition.Names) do EVENT_WORLD_NAMES[normalizedName(name)] = true end\10end\10\10local boundContainers = setmetatable({}, { __mode = \"k\" })\10local function relevantWorldObject(object)\10    return object and (isFruitTool(object) or EVENT_WORLD_NAMES[normalizedName(object.Name)] == true)\10end\10\10local function bindEventContainer(container, kind)\10    if not container or boundContainers[container] then return end\10    boundContainers[container] = true\10    if kind == \"enemies\" or kind == \"npcs\" then\10        trackSignal(container.ChildAdded, requestScan)\10        trackSignal(container.ChildRemoved, requestScan)\10    elseif kind == \"world\" then\10        trackSignal(container.ChildAdded, function(object)\10            if object.Name == \"Locations\" then\10                bindEventContainer(object, \"islands\")\10                requestScan()\10            elseif relevantWorldObject(object) then requestScan() end\10        end)\10        trackSignal(container.ChildRemoved, function(object)\10            if object.Name == \"Locations\" or relevantWorldObject(object) then requestScan() end\10        end)\10    elseif kind == \"islands\" then\10        trackSignal(container.DescendantAdded, function(object)\10            if EVENT_WORLD_NAMES[normalizedName(object.Name)] then requestScan() end\10        end)\10        trackSignal(container.DescendantRemoving, function(object)\10            if EVENT_WORLD_NAMES[normalizedName(object.Name)] then requestScan() end\10        end)\10    end\10end\10\10local boundSkies = setmetatable({}, { __mode = \"k\" })\10local function bindMoonSky(sky)\10    if not sky or not sky:IsA(\"Sky\") or boundSkies[sky] then return end\10    boundSkies[sky] = true\10    trackSignal(sky:GetPropertyChangedSignal(\"MoonTextureId\"), requestScan)\10end\10\10local function bindEventSignals()\10    bindEventContainer(workspace:FindFirstChild(\"Enemies\"), \"enemies\")\10    bindEventContainer(workspace:FindFirstChild(\"NPCs\"), \"npcs\")\10    bindEventContainer(workspace:FindFirstChild(\"_WorldOrigin\"), \"world\")\10    bindEventContainer(workspace:FindFirstChild(\"Map\"), \"islands\")\10    local origin = workspace:FindFirstChild(\"_WorldOrigin\")\10    bindEventContainer(origin and origin:FindFirstChild(\"Locations\"), \"islands\")\10    bindMoonSky(Lighting:FindFirstChildOfClass(\"Sky\"))\10\10    trackSignal(workspace.ChildAdded, function(object)\10        if object.Name == \"Enemies\" then bindEventContainer(object, \"enemies\"); requestScan()\10        elseif object.Name == \"NPCs\" then bindEventContainer(object, \"npcs\"); requestScan()\10        elseif object.Name == \"_WorldOrigin\" then\10            bindEventContainer(object, \"world\")\10            bindEventContainer(object:FindFirstChild(\"Locations\"), \"islands\")\10            requestScan()\10        elseif object.Name == \"Map\" then bindEventContainer(object, \"islands\"); requestScan()\10        elseif isFruitTool(object) then requestScan() end\10    end)\10    trackSignal(workspace.ChildRemoved, function(object)\10        if object.Name == \"Enemies\" or object.Name == \"NPCs\" or object.Name == \"_WorldOrigin\"\10            or object.Name == \"Map\" or isFruitTool(object) then requestScan() end\10    end)\10    trackSignal(CollectionService:GetInstanceAddedSignal(\"BerryBush\"), requestScan)\10    trackSignal(CollectionService:GetInstanceRemovedSignal(\"BerryBush\"), requestScan)\10    trackSignal(Lighting:GetAttributeChangedSignal(\"MoonPhase\"), requestScan)\10    trackSignal(Lighting.ChildAdded, function(object) bindMoonSky(object); if object:IsA(\"Sky\") then requestScan() end end)\10    trackSignal(Lighting.ChildRemoved, function(object) if object:IsA(\"Sky\") then requestScan() end end)\10end\10\10bindEventSignals()\10\10local function credentialValid()\10    return type(State.Credential) == \"string\"\10        and State.Credential ~= \"\"\10        and State.CredentialExpiresAt - unixNow() > (Config.AccessKey == \"\" and 60 or Config.CredentialRefreshLead)\10end\10\10local function disableForSession(message)\10    State.DisabledByServer = true\10    State.Running = false\10    State.Pending = {}\10    setStatus(message or \"Event network disabled by server\", true)\10    notify(\"Cokeboys Event Network\", State.Status)\10end\10\10local function acquireCredential(force)\10    if not State.Alive or State.DisabledByServer then return false, \"Event network disabled for this session\" end\10    if not force and credentialValid() then return true end\10    if State.AuthBusy then return false, \"Credential request already running\" end\10    if os.clock() < (State.AuthRetryAt or 0) then return false, \"Event authentication is cooling down\" end\10    if Config.AccessKey == \"\" then return false, \"No validated access key was supplied to the event collector\" end\10    local hwid = resolveHWID()\10    if hwid == \"\" then return false, \"Set HWID or use an executor that exposes gethwid()\" end\10\10    State.AuthBusy = true\10    State.AuthRetryAt = os.clock() + 30\10    setStatus(\"Requesting temporary event credential\")\10    local response, requestError = httpRequest(\10        \"POST\",\10        Config.CredentialURL,\10        HttpService:JSONEncode({\10            key = Config.AccessKey,\10            hwid = hwid,\10            username = LocalPlayer.Name,\10            game = \"Blox Fruits\",\10        })\10    )\10    State.AuthBusy = false\10    if not response then\10        setStatus(\"Credential request failed: \" .. tostring(requestError), true)\10        return false, State.Status\10    end\10    local decoded = decodeJSON(response.Body) or {}\10    if response.StatusCode == 503 and decoded.code == \"event_credentials_disabled\" then\10        disableForSession(\"Event credentials are disabled by Cokeboys\")\10        return false, State.Status\10    end\10    if response.StatusCode < 200 or response.StatusCode >= 300\10        or decoded.success ~= true or type(decoded.credential) ~= \"string\" then\10        setStatus(\"Credential rejected (HTTP \" .. tostring(response.StatusCode) .. \"): \"\10            .. tostring(decoded.message or decoded.error or \"unknown response\"), true)\10        return false, State.Status\10    end\10    if not State.Alive or State.DisabledByServer then return false, \"Event client stopped\" end\10    State.AuthRetryAt = 0\10    State.Credential = decoded.credential\10    State.ReporterId = tostring(decoded.reporterId or \"\")\10    State.CredentialExpiresAt = tonumber(decoded.expiresAt) or (unixNow() + 3600)\10    setStatus(\"Authenticated \226\128\162 event reporting ready\")\10    return true\10end\10\10local function eventPayload(event, active)\10    local uptime = serverUptime()\10    local server = {\10        sea = PLACE_TO_SEA[game.PlaceId] or 0,\10        players = #Players:GetPlayers(),\10        maxPlayers = Players.MaxPlayers,\10    }\10    local region = serverRegion()\10    if region then server.region = region end\10    if uptime then server.uptimeSeconds = uptime end\10    local payloadEvent = { type = event.Type, active = active == true }\10    if event.Value ~= \"\" then payloadEvent.value = event.Value end\10    return {\10        version = 2,\10        reporterId = State.ReporterId,\10        jobId = tostring(game.JobId),\10        placeId = game.PlaceId,\10        observedAt = unixNow(),\10        server = server,\10        event = payloadEvent,\10    }\10end\10\10local function queueEvent(event, active)\10    local existing = State.Pending[event.Key]\10    State.Pending[event.Key] = {\10        Key = event.Key,\10        Type = event.Type,\10        Value = event.Value,\10        Active = active == true,\10        RequestedAt = existing and existing.RequestedAt or os.clock(),\10        Priority = active and (EVENT_PRIORITY[event.Type] or 50) or 0,\10    }\10end\10\10local function reconcileEvents(current)\10    State.Detected = current\10    local now = unixNow()\10    for key, event in pairs(current) do\10        local reported = State.Reported[key]\10        if not reported or now - reported.AcceptedAt >= (EVENT_REFRESH_SECONDS[event.Type] or 60) then\10            queueEvent(event, true)\10        end\10    end\10    for key, reported in pairs(State.Reported) do\10        if not current[key] then\10            queueEvent({ Key = key, Type = reported.Type, Value = reported.Value }, false)\10        end\10    end\10    for key, pending in pairs(State.Pending) do\10        if pending.Active and not current[key] and not State.Reported[key] then\10            State.Pending[key] = nil\10        end\10    end\10end\10\10local function nextPending()\10    local best\10    for _, pending in pairs(State.Pending) do\10        if not best\10            or pending.Priority < best.Priority\10            or (pending.Priority == best.Priority and pending.RequestedAt < best.RequestedAt) then\10            best = pending\10        end\10    end\10    return best\10end\10\10local function headerNumber(headers, wanted)\10    for name, value in pairs(headers or {}) do\10        if tostring(name):lower() == wanted:lower() then return tonumber(value) end\10    end\10    return nil\10end\10\10local function sendPending(pending)\10    local authenticated, authError = acquireCredential(false)\10    if not authenticated then return false, authError end\10    local response, requestError = httpRequest(\10        \"POST\",\10        Config.APIBaseURL .. \"/v1/events\",\10        HttpService:JSONEncode(eventPayload(pending, pending.Active)),\10        -- Some mobile executors (Delta) overwrite Authorization with their own\10        -- session token on every request, so the credential also rides a custom\10        -- header they leave intact. Authorization stays for everything else.\10        {\10            Authorization = \"Bearer \" .. State.Credential,\10            [\"X-Cokeboys-Credential\"] = State.Credential,\10        }\10    )\10    State.LastRequestAt = os.clock()\10    if not response then\10        State.BackoffUntil = os.clock() + 15\10        setStatus(\"Event request failed: \" .. tostring(requestError), true)\10        return false, State.Status\10    end\10    local decoded = decodeJSON(response.Body) or {}\10    if response.StatusCode == 401 then\10        State.Credential = nil\10        State.CredentialExpiresAt = 0\10        State.BackoffUntil = os.clock() + 2\10        setStatus(\"Event credential expired \226\128\162 refreshing\")\10        return false, State.Status\10    end\10    if response.StatusCode == 503 and decoded.code == \"event_network_disabled\" then\10        disableForSession(\"Event network disabled by Cokeboys\")\10        return false, State.Status\10    end\10    if response.StatusCode == 429 then\10        State.BackoffUntil = os.clock() + (headerNumber(response.Headers, \"retry-after\") or 60)\10        setStatus(\"Event API rate limited \226\128\162 waiting\")\10        return false, State.Status\10    end\10    if response.StatusCode < 200 or response.StatusCode >= 300 or decoded.accepted ~= true then\10        State.Pending[pending.Key] = nil\10        setStatus(\"Event rejected (HTTP \" .. tostring(response.StatusCode) .. \"): \"\10            .. tostring(decoded.error or \"unknown response\"), true)\10        return false, State.Status\10    end\10\10    State.Pending[pending.Key] = nil\10    if pending.Active then\10        State.Reported[pending.Key] = {\10            Type = pending.Type,\10            Value = pending.Value,\10            AcceptedAt = unixNow(),\10        }\10    else\10        State.Reported[pending.Key] = nil\10    end\10    State.LastAccepted = {\10        Type = pending.Type,\10        Value = pending.Value,\10        Active = pending.Active,\10        At = unixNow(),\10    }\10    setStatus((pending.Active and \"Reported \" or \"Removed \") .. pending.Type\10        .. (pending.Value ~= \"\" and (\" \226\128\162 \" .. pending.Value) or \"\"))\10    return true\10end\10\10local function countEntries(dictionary)\10    local count = 0\10    for _ in pairs(dictionary) do count = count + 1 end\10    return count\10end\10\10function Reporter.GetSnapshot()\10    local detected = {}\10    for _, event in pairs(State.Detected) do\10        table.insert(detected, { Type = event.Type, Value = event.Value })\10    end\10    table.sort(detected, function(a, b)\10        return a.Type == b.Type and a.Value < b.Value or a.Type < b.Type\10    end)\10    return {\10        Version = Reporter.Version,\10        Alive = State.Alive,\10        Running = State.Running,\10        DisabledByServer = State.DisabledByServer,\10        Status = State.Status,\10        LastError = State.LastError,\10        CredentialReady = credentialValid(),\10        CredentialExpiresAt = State.CredentialExpiresAt,\10        ReporterId = State.ReporterId,\10        LastHTTPStatus = State.LastHTTPStatus,\10        LastAccepted = State.LastAccepted,\10        LegendarySwordStock = State.LegendarySwordStock,\10        Detected = detected,\10        DetectedCount = countEntries(State.Detected),\10        ReportedCount = countEntries(State.Reported),\10        PendingCount = countEntries(State.Pending),\10    }\10end\10function Reporter.SetAccess(accessKey, hwid)\10    Config.AccessKey = tostring(accessKey or \"\")\10    Config.HWID = tostring(hwid or \"\")\10    State.Credential = nil\10    State.ReporterId = nil\10    State.CredentialExpiresAt = 0\10    State.AuthRetryAt = 0\10    if State.Running then task.spawn(acquireCredential, true) end\10    return Config.AccessKey ~= \"\", Config.HWID ~= \"\" or resolveHWID() ~= \"\"\10end\10\10function Reporter.Rescan()\10    State.ScanRequested = true\10    return true\10end\10\10function Reporter.PreviewLocal()\10    local ok, events = pcall(scanEvents)\10    if not ok then\10        setStatus(\"Local preview failed: \" .. tostring(events), true)\10        return false, State.Status\10    end\10    State.Detected = events\10    local detected = {}\10    for _, event in pairs(events) do\10        table.insert(detected, { Type = event.Type, Value = event.Value })\10    end\10    table.sort(detected, function(a, b)\10        return a.Type == b.Type and a.Value < b.Value or a.Type < b.Type\10    end)\10    setStatus(\"Local preview complete \226\128\162 \" .. tostring(#detected) .. \" active sighting(s)\")\10    return true, detected\10end\10\10function Reporter.TestConnection()\10    local response, requestError = httpRequest(\"GET\", Config.APIBaseURL .. \"/health\")\10    if not response then return false, requestError end\10    local decoded = decodeJSON(response.Body) or {}\10    if response.StatusCode == 200 and decoded.ok == true then\10        return true, decoded\10    end\10    return false, decoded.error or (\"HTTP \" .. tostring(response.StatusCode))\10end\10\10function Reporter.Start()\10    if not State.Alive then return false, \"Reporter has been stopped and must be re-executed\" end\10    if State.Running then return true, State.Status end\10    if not PLACE_TO_SEA[game.PlaceId] then\10        setStatus(\"This Blox Fruits place is not supported by the event collector\", true)\10        return false, State.Status\10    end\10    if not RequestFunction then\10        setStatus(\"Executor HTTP request function unavailable\", true)\10        return false, State.Status\10    end\10    if State.DisabledByServer then return false, \"Event network disabled for this session\" end\10    local ok, message = acquireCredential(false)\10    if not ok then return false, message end\10    State.Running = true\10    State.ScanRequested = true\10    setStatus(\"Running \226\128\162 scanning current server\")\10    notify(\"Cokeboys Event Network\", \"Event collector started\")\10    return true, State.Status\10end\10\10function Reporter.Stop(reason)\10    if not State.Alive then return true end\10    State.Running = false\10    State.Alive = false\10    State.Status = tostring(reason or \"Stopped\")\10    Config.AccessKey = \"\"\10    Config.HWID = \"\"\10    Stat